mapper.select:
SELECT vi.invitation_id invitationId, vi.visit_type visitType, vi.visit_time visitTime, vi.is_come isCome,vi.qr_code qrCode,
       vi.invitation_reason invitationReason, v.visitor_id visitorId, v.no, v.`name`, v.tel, v.unit, v.id_card idCard,vi.create_time createTime,
       v.license
FROM visit_invitation vi
LEFT JOIN visitor v ON v.invitation_id = vi.invitation_id AND v.status_cd = '0'
WHERE vi.invitation_id IN (
    SELECT temp.id
    FROM (
        SELECT DISTINCT vi.invitation_id id
        FROM visit_invitation vi
        LEFT JOIN visitor v ON v.invitation_id = vi.invitation_id AND v.status_cd = '0'
        WHERE vi.status_cd = '0' AND vi.community_id = #{communityId}

            and v.name like concat('%', #{name}, '%')


            and v.unit like concat('%', #{unit}, '%')


            and vi.is_come = #{isCome}


            and vi.visit_time >=  #{lessVisitTime}


            and vi.visit_time <=  #{moreVisitTime}


            and vi.user_id = #{userId}


            limit #{page}, #{row}

    ) AS temp
)

SELECT COUNT(DISTINCT vi.invitation_id) count
FROM visit_invitation vi
LEFT JOIN visitor v ON v.invitation_id = vi.invitation_id AND v.status_cd = '0'
WHERE vi.status_cd = '0' AND vi.community_id = #{communityId}

    and v.name like concat('%', #{name}, '%')


    and v.unit like concat('%', #{unit}, '%')


    and vi.is_come = #{isCome}


    and vi.visit_time >=  #{lessVisitTime}


    and vi.visit_time <=  #{moreVisitTime}


    and vi.user_id = #{userId}

SELECT invitation_id invitationId, visit_type visitType, visit_time visitTime, is_come isCome, unique_code uniqueCode, user_id userId, qr_code qrCode, community_id communityId
FROM visit_invitation
WHERE invitation_id = #{invitationId} AND status_cd = #{statusCd}

